<?php
session_start();header('Content-Type: application/json; charset=utf-8');require_once(__DIR__.'/../../../Database/db/db.php');require_once(__DIR__.'/../../../utils/security/csrf/csrf.php');
$respond=static function(int $status,array $body):never{http_response_code($status);echo json_encode($body);exit;};if($_SERVER['REQUEST_METHOD']!=='POST')$respond(405,['success'=>false,'message'=>'POST required']);if(($_SESSION['role']??'')!=='student'||empty($_SESSION['user_id']))$respond(401,['success'=>false,'message'=>'Student sign-in required']);$lessonId=filter_var($_POST['lesson_id']??null,FILTER_VALIDATE_INT);$note=trim((string)($_POST['note_content']??''));$token=$_POST['csrf_token']??($_SERVER['HTTP_X_CSRF_TOKEN']??'');if(!$lessonId||$note==='')$respond(422,['success'=>false,'message'=>'Lesson and note are required']);if(mb_strlen($note)>2000)$respond(422,['success'=>false,'message'=>'Note is too long']);if(!is_string($token)||!CSRF::validateToken($token))$respond(403,['success'=>false,'message'=>'Security token expired. Refresh the page.']);try{$pdo=get_db();$q=$pdo->prepare("SELECT 1 FROM course_lessons cl JOIN course_modules cm ON cm.id=cl.module_id JOIN enrollments e ON e.course_id=cm.course_id AND e.user_id=? AND e.status IN ('active','completed') WHERE cl.id=? AND cl.is_active=1 AND cm.is_active=1 LIMIT 1");$q->execute([(int)$_SESSION['user_id'],$lessonId]);if(!$q->fetchColumn())$respond(403,['success'=>false,'message'=>'You must be enrolled in this course to add lesson notes.']);$q=$pdo->prepare('INSERT INTO lesson_notes (user_id,lesson_id,note_content) VALUES (?,?,?)');$q->execute([(int)$_SESSION['user_id'],$lessonId,$note]);$respond(200,['success'=>true,'message'=>'Note saved.','id'=>(int)$pdo->lastInsertId(),'created_at'=>date(DATE_ATOM)]);}catch(Throwable $e){error_log('LMS note save failed: '.$e->getMessage());$respond(500,['success'=>false,'message'=>'Unable to save this note right now.']);}
